 7→object CatalogMergeStrategy : MergeStrategy<Catalog> {
 8→    private val logger by logger()
 9→
10→    override fun merge(documents: List<ChangedData<Catalog>>): List<ChangedData<Catalog>> {
11→        return documents
12→            .groupBy { it.id } // 같은 문서로 그룹핑
13→            .map { (_, group) ->
14→                if (group.size == 1) {
15→                    group.first()
16→                } else {
17→                    group.sortedBy { it.offset } // offset 기준으로 정렬
18→                        .fold(null as ChangedData<Catalog>?) { acc, current ->
19→                            merge(acc, current)
20→                                .also {
21→                                    if (it == null) {
22→                                        // Note. merge result가 null인 경우, acc는 not null이 보장됨
23→                                        logger.warn { "[Catalog Merge Strategy] Unexpected operation. "  + diffLog(acc!!, current) }
24→                                    }
25→                            }
26→                        }
27→                }
28→            }
29→            .filterNotNull()
30→    }
31→}
