 8→object CatalogFilter {
 9→    private val logger by logger()
10→
11→    /**
12→     * 색인이 불가한 문서를 필터링합니다.
13→     *
14→     * Note. 필터링된 ids를 모아서 로깅하면 warn log monitor 민감도가 떨어질 수 있어 id마다 로깅합니다.
15→     */
16→    fun filter(document: ChangedData<Catalog>): Boolean {
17→        if (document.op == Operation.CREATE || document.op == Operation.UPDATE) {
18→            // afterData 확인
19→            if (document.afterData == null) {
20→                log(document, "afterData must not be null.")
21→                return false
22→            }
23→
24→            // categoryId 확인
25→            if (document.afterData.categoryId == null || document.afterData.categoryId == 0) {
26→                log(document, "categoryId must not be null.")
27→                return false
28→            }
29→
30→            // manufacturerId 확인
31→            if (document.afterData.manufacturerId == null || document.afterData.manufacturerId == 0L) {
32→                log(document, "manufacturerId must not be null.")
33→                return false
34→            }
35→        }
36→
37→        return true
38→    }
39→
40→    private fun log(document: ChangedData<Catalog>, message: String) {
41→        logger.warn { "[Catalog Filter] Skipped - $message" +
42→                " catalogId=${document.id}, partition=${document.partition}, offset=${document.offset}" }
43→    }
44→}
